// Native renderer oracles use current installed source in portable VM. No
// authored renderer, CSS or provider executes in this browser or Node host.
const {test,before,after}=require('node:test'),assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const {chromium,executablePath}=require('../scripts/codex/browser.cjs');
const root=path.resolve(__dirname,'..');
const ids=['one-oh-one','domino','durak','checkers','snakes','ludo','pexeso','fleet-grid','dice-poker','oldmaid','gofish','klondike','spider','mage-brawl','tictactoe'];
const scripts=['core/protocol.js','core/messages.js','platform/web/dom.js','core/player-palette.js','core/token-layout.js','platform/web/progress-surface.js','platform/web/expandable-notice.js','core/icons.js','core/vector-art.js','core/component-assets.js','core/game-components.js','core/mini-split-deck.js','core/color-value-deck.js','core/rank-cards.js','core/solitaire-board.js','core/elemental-arena.js','core/player-target.js','presentation/plan-player.js','presentation/scheduler.js','platform/web/sdk-canvas.js','platform/web/scene-images.js','platform/web/sdk-scene.js'];
const styles=['platform/web/notices.css','core/player-target.css','core/view-kit.css','core/game-components.css','core/rank-cards.css','core/solitaire-board.css','core/elemental-arena.css','platform/web/sdk-scene.css'];
let environment,E,browser,server,base;
before(async()=>{
 // Scoped scene tests use the supplied companion. The full-scene case
 // validates its complete roster when selected.
 environment=await require('./sdk-installed.cjs').bootstrap();E=environment.engine;
 server=http.createServer((request,response)=>{const file=request.url.slice(1);if(!file){response.setHeader('content-type','text/html');response.end('<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+styles.map(f=>'<link rel="stylesheet" href="/'+f+'">').join('')+scripts.map(f=>'<script defer src="/'+f+'"></script>').join('')+'<main id="scene"></main><nav id="host-actions"></nav>');return;}if(![...scripts,...styles].includes(file)){response.writeHead(404).end();return;}response.setHeader('content-type',file.endsWith('.js')?'text/javascript':'text/css');response.end(fs.readFileSync(path.join(root,file)));});
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));base='http://127.0.0.1:'+server.address().port;
 browser=await chromium.launch({headless:true,executablePath:executablePath()});
});
after(async()=>{await browser?.close();if(server)await new Promise(resolve=>server.close(resolve));environment?.close();});
const canonical=value=>JSON.stringify(value,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.entries(v).sort(([a],[b])=>a.localeCompare(b))):v);
async function session(t,game,{count,preset,seed=17,options={},prepare}={}){
 const spec=E.get(game);let state=E.createGame(game,{seed,preset:preset||spec.presets[0].id,...options,players:Array.from({length:count??Math.min(2,spec.max)},(_,i)=>({name:'Игрок '+(i+1)}))});if(prepare)prepare(state);assert(E.validateState(state));let viewer=state.turn;
 const source=require('../core/packs.js').sdkSource(environment.bundles.find(b=>b.manifest.id===game));
 const frame=()=>{const p=E.project(state,viewer);return {now:0,pack:{hash:game+'-fixture'},projection:p.modelProjection,scene:p.scene,support:p.scene.support,resources:{assets:source.assets||[]},actions:p.modelProjection.actions.map(command=>({command,label:E.get(game).decorate(command,p.modelProjection,state.players).label})),history:{reviewing:false},hostMarkup:environment.views.render(p,viewer,E.legalActions(state,viewer),{})};};
 const context=await browser.newContext({viewport:{width:1280,height:1000},reducedMotion:'reduce',playroomProfile:false});t.after(()=>context.close());const page=await context.newPage(),errors=[],committed=[];page.on('pageerror',error=>errors.push(error.message));
 await page.exposeFunction('commitCase',command=>{assert(frame().projection.actions.some(a=>canonical(a)===canonical(command)),'native command is currently authorized');state=E.applyAction(state,viewer,command);committed.push(command);return frame();});
 await page.goto(base);await page.evaluate(()=>{window.caseRenderer=new PlayroomSDKSceneRenderer(document.querySelector('#scene'),{text:value=>typeof value==='string'?value:value?.key||String(value??''),command:async command=>{const next=await commitCase(command);paintCase(next);return true;},error:error=>{throw Error(error.code);}});window.paintCase=frame=>{caseRenderer.update(frame);const template=document.createElement('template');template.innerHTML=frame.hostMarkup||'';const host=document.querySelector('#host-actions');host.replaceChildren(...[...template.content.querySelectorAll('[data-action]')].map(button=>{button.onclick=()=>{const action=JSON.parse(button.dataset.action),command=caseRenderer.frame.projection.actions.find(c=>Object.keys(c).every(key=>JSON.stringify(c[key])===JSON.stringify(action[key])));if(command)caseRenderer.command(command);};return button;}));};});
 const update=async extra=>page.evaluate(frame=>paintCase(frame),{...frame(),...extra});await update();
 return {page,errors,committed,frame,update,get state(){return state;},async viewer(value){viewer=value;await update();},async close(){await page.evaluate(()=>caseRenderer.destroy());assert.deepEqual(errors,[]);}};
}
const artSelector='#scene .sdk-piece-card:not(.is-empty),#scene .sdk-board-piece,#scene .sdk-die';
async function remember(page){return page.evaluate(selector=>{window.savedArt=new Map([...document.querySelectorAll(selector)].map(e=>[JSON.stringify(e._target),{element:e,art:e.firstElementChild,signature:e._cardSignature??e._pieceSignature??e._dieSignature??e._graphicSignature}]));return savedArt.size;},artSelector);}
async function retained(page){return page.evaluate(selector=>{const current=new Map([...document.querySelectorAll(selector)].map(e=>[JSON.stringify(e._target),e]));let comparable=0,replaced=0,details=[];for(const [key,old]of savedArt){const e=current.get(key);if(e&&(e._cardSignature??e._pieceSignature??e._dieSignature??e._graphicSignature)===old.signature){comparable++;if(e!==old.element||e.firstElementChild!==old.art){replaced++;details.push({key,node:e!==old.element,art:e.firstElementChild!==old.art});}}}return {comparable,replaced,details};},artSelector);}
async function stable(s){const count=await remember(s.page);assert(count>0,'the oracle observes real component artwork');await s.update({now:1000});const same=await retained(s.page);assert.equal(same.comparable,count);assert.equal(same.replaced,0,'irrelevant clock update retains every unchanged component node and SVG');}
async function target(page,target,{optional=false}={}){const index=await page.evaluate(target=>[...document.querySelectorAll('#scene [data-sdk-target]')].map((e,index)=>({e,index})).filter(({e})=>!e.disabled&&caseRenderer.sameTarget(target,e._target)).sort((a,b)=>Number(!!b.e._target.entity)-Number(!!a.e._target.entity))[0]?.index??-1,target);if(optional&&index<0)return null;assert(index>=0,'authorized source/target has a native enabled endpoint '+JSON.stringify(target));return page.locator('#scene [data-sdk-target]').nth(index);}
async function native(s,command){const before=s.committed.length,revision=s.frame().projection.revision,interaction=s.frame().scene.interactions.find(i=>canonical(i.command)===canonical(command));assert(interaction,'scene binds exact wire command');
 const direct=interaction.source?-1:await s.page.evaluate(command=>[...document.querySelectorAll('#scene [data-sdk-command]')].findIndex(e=>!e.disabled&&JSON.stringify(e._command)===JSON.stringify(command)),command);if(direct>=0)await s.page.locator('#scene [data-sdk-command]').nth(direct).click();else if(interaction.source)await (await target(s.page,interaction.source)).click();if(s.committed.length===before&&direct<0){const destination=await target(s.page,interaction.target,{optional:true});if(destination)await destination.click(await destination.evaluate(e=>e.classList.contains('board-target'))?{position:{x:3,y:3}}:{});else{assert(!interaction.source,'physical moves require a scene destination');const index=await s.page.evaluate(command=>[...document.querySelectorAll('#host-actions [data-action]')].findIndex(e=>{const action=JSON.parse(e.dataset.action);return Object.keys(command).every(key=>JSON.stringify(command[key])===JSON.stringify(action[key]));}),command);assert(index>=0,'canonical host action bar retains source-free command '+command.type);await s.page.locator('#host-actions [data-action]').nth(index).click();}}
 await s.page.waitForFunction(revision=>caseRenderer.frame.projection.revision>revision||!caseRenderer.choicePanel.hidden,revision);
 if(s.committed.length===before&&await s.page.locator('.sdk-choice-panel').isVisible()){
  const index=await s.page.evaluate(command=>[...document.querySelectorAll('.sdk-choice-panel button')].findIndex(e=>JSON.stringify(e._command)===JSON.stringify(command)),command);
  if(index>=0)await s.page.locator('.sdk-choice-panel button').nth(index).click();else{const commands=s.frame().scene.interactions.filter(i=>canonical(i.source)===canonical(interaction.source)&&canonical(i.target)===canonical(interaction.target)).map(i=>i.command),fields=Object.keys(command).filter(key=>commands.some(c=>JSON.stringify(c[key])!==JSON.stringify(command[key]))&&commands.every(c=>['string','number','boolean'].includes(typeof c[key])));for(const key of fields){const schema=s.frame().scene.commandParameters?.[key],label=schema?.values?.find(choice=>choice.value===command[key])?.label;if(label)await s.page.locator('.sdk-choice-panel').getByRole('button',{name:typeof label==='string'?label:label.key,exact:true}).click();}await s.page.locator('.sdk-choice-panel .sdk-primary').click();}
 }
 await s.page.waitForFunction(revision=>caseRenderer.frame.projection.revision===revision,revision+1);assert.equal(s.committed.length,before+1,'exactly one native command commits');assert.deepEqual(s.committed.at(-1),command);
}
async function permissions(s){const publicObjects=new Set((s.frame().scene.objects||[]).map(o=>o.ref.namespace+'-'+o.ref.id)),shown=await s.page.locator('#scene [data-entity]').evaluateAll(nodes=>nodes.map(n=>n.dataset.entity));for(const id of shown)assert(publicObjects.has(id),'only authorized physical IDs enter DOM: '+id);await s.update({history:{reviewing:true}});assert.equal(await s.page.locator('#scene [data-sdk-target]:not([disabled])').count(),0,'history contains no live source or target permission');assert.equal(await s.page.locator('.sdk-cross-route .is-playable,.sdk-cross-route .board-target').count(),0,'history has no live pawn or destination highlights');await s.update();}

test('scene targets match projected commands even when nested key order differs',async t=>{
 const s=await session(t,'checkers');
 const matched=await s.page.evaluate(()=>{
  const command={type:'move',to:{row:1,col:2}},sceneCommand={to:{col:2,row:1},type:'move'};
  const frame={...caseRenderer.frame,projection:{...caseRenderer.frame.projection,actions:[command]},
    scene:{contractVersion:1,id:'target-order',family:'board',zones:[],objects:[],players:[],
      interactions:[{kind:'activate',target:{zone:'field'},command:sceneCommand}]}};
  caseRenderer.update(frame);
  return caseRenderer.commandsAt({zone:'field'});
 });
 assert.deepEqual(matched,[{type:'move',to:{row:1,col:2}}]);
 await s.close();
});

test('closed renderer ignores domain and authority fields for all current installed scenes',async t=>{
 const s=await session(t,'klondike');
 for(const bundle of environment.bundles){const game=bundle.manifest.id;const spec=E.get(game),state=E.createGame(game,{seed:17,preset:spec.presets[0].id,players:Array.from({length:Math.min(2,spec.max)},()=>({name:'A'}))}),p=E.project(state,0),source=require('../core/packs.js').sdkSource(bundle),frame={projection:p.modelProjection,scene:p.scene,support:p.scene.support,resources:{assets:source.assets||[]},history:{reviewing:false},actions:[]};await s.page.evaluate(f=>caseRenderer.update(f),frame);const before=await s.page.locator('#scene').innerHTML();await s.page.evaluate(f=>caseRenderer.update({...f,projection:{...f.projection,data:{secret:'DO_NOT_READ'},authoritySecret:'DO_NOT_READ',modelProjection:{secret:true}}}),frame);assert((await s.page.locator('#scene').innerHTML())===before,game+' renderer uses scene only');const lease=await s.page.evaluate(frame=>{const root=document.getElementById('scene'),surface=caseRenderer.surface,template=document.createElement('template');template.innerHTML='<main id="scene"></main><nav id="host-actions"></nav>';PlayroomDOM.patchChildren(document.body,template.content);paintCase(frame);return root===document.getElementById('scene')&&surface.isConnected&&surface.parentElement===root&&root.classList.contains('sdk-scene');},frame);assert(lease,game+' survives a shell patch without detaching its owned scene nodes');}
 const resource=await s.page.evaluate(async()=>{const data='<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16"><title>Рубашка</title><rect width="16" height="16" fill="#345"/></svg>';caseRenderer.prepareResources({assets:[{file:'assets/utf8.svg',mime:'image/svg+xml',encoding:'utf8',data,sha256:'utf8-resource-case'}]});const url=caseRenderer.imageAsset('assets/utf8.svg').url,text=await(await fetch(url)).text(),image=new Image();image.src=url;await image.decode();return {text,expected:data,width:image.naturalWidth,height:image.naturalHeight};});assert.equal(resource.text,resource.expected,'UTF-8 vector resources retain their exact Unicode source');assert.deepEqual([resource.width,resource.height],[16,16]);
 const fault=await s.page.evaluate(frame=>{const paint=caseRenderer.renderSemantic;let caught=false;caseRenderer.renderSemantic=()=>{throw Error('synthetic semantic paint failure');};try{caseRenderer.update(frame);}catch(error){caught=error.message==='synthetic semantic paint failure';}finally{caseRenderer.renderSemantic=paint;}return {caught,debugRows:[...document.querySelectorAll('.sdk-zones,.sdk-objects')].filter(e=>!e.hidden&&e.getBoundingClientRect().height>0).length};},s.frame());assert.deepEqual(fault,{caught:true,debugRows:0},'a handled paint failure never exposes internal SDK workbench rows');
 await s.close();
});

test('solitaire keeps unaffected card artwork across native move, undo, draw and selection',async t=>{
 for(const game of ['klondike','spider']){const s=await session(t,game),S=require('../presentation/scene-contract.js'),scene=s.frame().scene;assert.equal(S.validate(scene,1),scene);assert.equal(S.commands(scene,s.frame().projection),scene);for(const change of [s=>{s.tableau.find(col=>col.some(c=>c.hidden)).find(c=>c.hidden).id='hidden-authority-id';},s=>s.stockCount++,s=>s.dragSources.push('not-public'),s=>s.solitaireLayout.homes.push({suit:'♥',index:0}),s=>s.solitaireLayout.transfers.push({card:{id:'not-public',rank:14,suit:'♥',open:true},from:'waste',to:'home-♥'})]){const bad=JSON.parse(JSON.stringify(scene));change(bad);assert.throws(()=>S.validate(bad,1),/SCENE_SOLITAIRE_/);}const denied=JSON.parse(JSON.stringify(scene));denied.solitaireLayout.hints.push({type:'unauthorized-hint'});assert.throws(()=>S.commands(denied,s.frame().projection),/SCENE_COMMAND_DENIED/);await stable(s);const command=s.frame().projection.actions.find(a=>a.type==='move'&&a.source==='tableau');assert(command);await remember(s.page);await native(s,command);const same=await retained(s.page);assert(same.comparable>0);assert.equal(same.replaced,0,JSON.stringify({game,command,same}));for(const type of ['undo','draw']){const command=s.frame().projection.actions.find(a=>a.type===type);assert(command);await native(s,command);await permissions(s);}await s.close();}
});
