test('Domino retains tile SVGs through native plays on both ends and exact orientation previews',async t=>{
 const s=await session(t,'domino',{prepare:state=>{const tiles=new Map([...state.data.hands.flat(),...state.data.stock].map(c=>[c.id,c])),take=id=>{const tile=tiles.get(id);assert(tile);tiles.delete(id);return tile;};state.data.chain=[take('d11')];state.data.hands=[['d12','d13','d14','d15','d16','d01','d00'].map(take),['d22','d23','d24','d25','d26','d02','d03'].map(take)];state.data.stock=[...tiles.values()];state.data.passes=0;state.data.openingTileId='d11';state.turn=0;}});await stable(s);await s.update({ui:{quickPlay:true}});const select=s.frame().scene.interactions.find(i=>i.command.card==='d12'&&i.command.side==='right');await(await target(s.page,select.source)).click();assert.equal(s.committed.length,0,'Domino keeps select mode even when quick play is enabled');assert.equal(await s.page.locator('.sdk-chain-drop:not([disabled])').count(),2);const face=s.frame().scene.placements.find(p=>canonical(p.command)===canonical(select.command));assert.equal(await s.page.locator('.sdk-chain-drop:not([disabled])').filter({has:s.page.locator('[data-card-deck=domino]')}).count(),2);assert(await s.page.locator('.sdk-chain-drop:not([disabled])').evaluateAll((nodes,face)=>nodes.some(node=>Number(node.dataset.previewA)===face.a&&Number(node.dataset.previewB)===face.b),face));await s.page.locator('.sdk-cancel-selection').click();
 for(const [actor,id,side]of [[0,'d12','right'],[1,'d23','right'],[0,'d13','left'],[1,'d03','left'],[0,'d01','left']]){await s.viewer(actor);const command=s.frame().projection.actions.find(a=>a.card===id&&a.side===side);assert(command);if(id==='d01'){await s.update({ui:{quickPlay:true}});const before=s.committed.length,interaction=s.frame().scene.interactions.find(i=>canonical(i.command)===canonical(command));assert.equal(s.frame().scene.interactions.filter(i=>i.source&&canonical(i.source)===canonical(interaction.source)).length,1);await(await target(s.page,interaction.source)).click();assert.equal(s.committed.length,before,'a single-end domino move also waits for destination confirmation');}await remember(s.page);await native(s,command);const same=await retained(s.page);assert(same.comparable>0);assert.equal(same.replaced,0);await permissions(s);}await s.close();
 const drawCase=await session(t,'domino',{prepare:state=>{const tiles=new Map([...state.data.hands.flat(),...state.data.stock].map(c=>[c.id,c])),take=id=>{const tile=tiles.get(id);assert(tile);tiles.delete(id);return tile;};state.data.chain=[take('d66')];state.data.hands=[['d01','d02','d03','d04','d05','d11','d12'].map(take),['d13','d14','d15','d22','d23','d24','d25'].map(take)];state.data.stock=[...tiles.values()];state.data.passes=0;state.data.openingTileId='d66';state.turn=0;}});const draw=drawCase.frame().projection.actions.find(command=>command.type==='draw');assert(draw,'a blocked real domino hand can draw from the bazaar');const stock=drawCase.state.data.stock.length;assert.equal(await drawCase.page.locator('.sdk-table-slot[aria-label="Колода"]').count(),0,'a bazaar count never renders a card stock');await native(drawCase,draw);assert.equal(drawCase.state.data.stock.length,stock-1);await drawCase.close();
});
test('Dice Poker retains unchanged dice and score rows across native roll hold and score actions',async t=>{
 const s=await session(t,'dice-poker');await stable(s);assert.equal(await s.page.locator('.sdk-score-sheet tbody tr').count(),17);assert.equal(await s.page.locator('.sdk-score-sheet button').count(),0,'unrolled categories stay inert');await s.viewer(-1);assert(s.frame().scene.dice.every(die=>die.value===null),'public unrolled dice are blank');assert.equal(await s.page.locator('.sdk-score-roll').isVisible(),false);await s.viewer(s.state.turn);await native(s,s.frame().projection.actions.find(a=>a.type==='roll'));assert.equal(await s.page.locator('.sdk-score-sheet button').count(),15);await remember(s.page);const rows=await s.page.locator('.sdk-score-sheet tbody').innerHTML();await native(s,s.frame().projection.actions.find(a=>a.type==='hold'));assert.equal(await s.page.locator('.sdk-score-sheet tbody').innerHTML(),rows);assert.equal(await s.page.locator('.sdk-die[aria-pressed="true"]').count(),1,'held state survives selection painting');assert.equal(await s.page.locator('.sdk-die.is-selected').count(),1,'native selected artwork follows the held state');const same=await retained(s.page);assert.equal(same.comparable,5,'holding a die changes its state without rebuilding any unchanged face');assert.equal(same.replaced,0);await native(s,s.frame().projection.actions.find(a=>a.type==='score'));await permissions(s);await s.close();
});
test('Pexeso rebuilds only opened slots and never caches hidden identities across native flips',async t=>{
 for(const deck of ['cartoon','52']){const s=await session(t,'pexeso',{preset:'easy',options:{deck}});assert.equal(await s.page.locator('.sdk-memory-slot').count(),16);assert.equal(await s.page.locator('.sdk-memory-slot .card-deck-art').count(),16,'backs keep the shared physical card material');const S=require('../presentation/scene-contract.js'),scene=s.frame().scene;for(const change of [s=>s.cards[0].card.id='private',s=>s.cards[0].index=16,s=>s.cards[0].matched=true,s=>s.cards[0].closing=true,s=>s.cards[1].id=s.cards[0].id,s=>s.skinFamilies=['../private']]){const bad=JSON.parse(JSON.stringify(scene));change(bad);assert.throws(()=>S.validate(bad,2),/SCENE_/);}await stable(s);const before=s.frame();const count=await remember(s.page);await native(s,s.frame().projection.actions.find(a=>a.type==='flip'&&a.index===0));const same=await retained(s.page);assert.equal(same.comparable,count-1);assert.equal(same.replaced,0);assert.equal(before.scene.cards[0].card.hidden,true);if(deck==='cartoon'){assert.equal(await s.page.locator('.sdk-memory-face [data-character-style="minimal"]').count(),2,'the framed character and its ink use the standard variant');await s.page.evaluate(()=>caseRenderer.cardSkin='simple');await s.update();assert.equal(await s.page.locator('.sdk-memory-face [data-character-style="simple"]').count(),2);await s.page.evaluate(()=>caseRenderer.cardSkin='minimal');await s.update();}const pair=c=>c.character||c.shape+'-'+c.color+(c.rank??'')+(c.rank?(['♥','♦'].includes(c.suit)?'red':'black'):'');const second=s.state.data.board.findIndex(c=>pair(c)!==pair(s.state.data.board[0]));assert(second>=0);await native(s,s.frame().projection.actions.find(a=>a.type==='flip'&&a.index===second));for(const viewer of [1,-1,0]){await s.viewer(viewer);await permissions(s);}await s.close();}
});
test('Go Fish and Old Maid retain authorized card art and counters through native commands and viewer changes',async t=>{
 for(const game of ['gofish','oldmaid']){const s=await session(t,game);await stable(s);for(let step=0;step<3;step++){await s.viewer(s.state.turn);const command=s.frame().projection.actions[0];assert(command);await native(s,command);await permissions(s);}for(const viewer of [1,-1,0]){await s.viewer(viewer);await permissions(s);}await s.close();}
 // A successful request forms a complete public set; collection rows and
 // previous rank prints remain mounted while the physical hand loses cards.
 const setupFish=state=>{const d=state.data,pool=new Map(Array.from({length:13},(_,i)=>['♠','♥','♦','♣'].map(suit=>({id:suit+(i+2),suit,rank:i+2}))).flat().map(c=>[c.id,c])),take=id=>{const c=pool.get(id);assert(c);pool.delete(id);return c;};d.books=[[2,5],[9],[],[7]];d.bookCards=d.books.map(ranks=>ranks.map(rank=>[...pool.values()].find(c=>c.rank===rank)));for(const rank of d.books.flat())for(const card of [...pool.values()])if(card.rank===rank)pool.delete(card.id);d.hands=[['♠8','♥8','♦8','♣3'],['♣8','♠4'],['♥3','♠6'],['♦3','♣4']].map(ids=>ids.map(take));d.drawPile=[...pool.values()];d.firstPlayer=0;d.attempts=Array(4).fill(0);state.turn=0;};
 const fish=await session(t,'gofish',{count:4,prepare:setupFish});assert.equal(await fish.page.locator('.sdk-collection-row').count(),4);assert.equal(await fish.page.locator('.sdk-collection-cards .mini-card').count(),4);assert.equal(await fish.page.locator('.sdk-player .sdk-book-cards .sdk-piece-card').count(),0,'public sets are on the table, not duplicated in hands');await fish.page.evaluate(()=>window.bookNodes=[...document.querySelectorAll('.sdk-collection-row,.sdk-collection-cards .mini-card')]);const ask=fish.frame().projection.actions.find(c=>c.type==='ask'&&c.cardId==='♠8'&&c.target===1);assert(ask);const interaction=fish.frame().scene.interactions.find(i=>canonical(i.command)===canonical(ask));await(await target(fish.page,interaction.source)).click();assert.equal(fish.committed.length,0);assert.equal(await fish.page.locator('.sdk-choice-panel').isVisible(),false,'a rank request uses native player targets, not a generic command list');await(await target(fish.page,interaction.target)).click();await fish.page.waitForFunction(()=>caseRenderer.frame.projection.revision===1);assert.deepEqual(fish.state.data.books[0],[2,5,8]);assert.equal(await fish.page.locator('.sdk-collection-cards .mini-card').count(),5);assert(await fish.page.evaluate(()=>bookNodes.every(n=>n.isConnected)),'unchanged collection rows and prints retain their DOM');await permissions(fish);await fish.close();
 const emptyStock=await session(t,'gofish',{count:4,prepare:state=>{setupFish(state);state.data.hands[1].push(...state.data.drawPile.splice(0));}});assert.equal(await emptyStock.page.locator('.sdk-collection-stock [data-card-slot=stock]').count(),1,'an exhausted stock uses the shared empty surface without a missing helper');await permissions(emptyStock);await emptyStock.close();
 const maid=await session(t,'oldmaid',{prepare:state=>{const d=state.data,deck=Array.from({length:9},(_,i)=>['♠','♥','♦','♣'].map(suit=>({id:suit+(i+6),suit,rank:i+6}))).flat().filter(c=>c.id!=='♣12'),take=id=>deck.find(c=>c.id===id);d.hands=[[take('♠8')],[take('♣8'),take('♠12')]];d.discard=deck.filter(c=>!['♠8','♣8','♠12'].includes(c.id));d.outOrder=[];d.points=[0,0];state.turn=0;}});assert.equal(await maid.page.locator('.sdk-pair-discard [data-entity]').count(),1,'only the latest public discard is mounted');await maid.viewer(1);assert((await maid.page.locator('[data-entity="card-♠12"]').innerHTML()).includes('card-crown'),'the unpaired queen keeps the original crown artwork');await maid.viewer(0);await native(maid,maid.frame().projection.actions.find(c=>c.cardIndex===0));assert.equal(maid.state.status,'finished');assert.equal(maid.state.data.discard.length,34);assert.equal(await maid.page.locator('.sdk-pair-discard [data-entity="card-♣8"]').count(),1);await permissions(maid);await maid.close();
});

test('Durak retains card faces stock and trump through native attack defence and current placements',async t=>{
 const s=await session(t,'durak');await stable(s);assert.equal(await s.page.locator('.sdk-trick-pair').count(),6);const bounds=await s.page.locator('.sdk-paired-tricks').boundingBox();
 const stock=s.page.locator('.sdk-trick-deck');
 assert.equal(await stock.locator('.shared-card-back:visible').count(),1);
 assert.equal(await stock.locator('.shared-card-slot:visible').count(),0);
 for(let step=0;step<3;step++){await s.viewer(s.state.turn);const command=s.frame().projection.actions.find(a=>a.card&&a.type!=='exchange')||s.frame().projection.actions[0];assert(command);await remember(s.page);await native(s,command);const same=await retained(s.page);assert(same.comparable>0);assert.equal(same.replaced,0);assert.deepEqual(await s.page.locator('.sdk-paired-tricks').boundingBox(),bounds,'fixed pair slots never reflow after a move');await permissions(s);}await s.close();
 // One selected card can beat either open attack. The chosen destination must
 // remain explicit; a generic table command cannot guess which pair to cover.
 const setup=(state,{transfer=false,exchange=false}={})=>{const d=state.data,pool=new Map([...d.hands.flat(),...d.drawPile].map(c=>[c.id,c])),take=id=>{const c=pool.get(id);assert(c);pool.delete(id);return c;};d.trump={...take('♠14')};d.table=exchange?[]:[{attack:take('♥6'),defense:null},...(!transfer?[{attack:take('♥7'),defense:null}]:[])];d.hands=[['♦6','♦7','♦8','♦9','♦10','♦11'].map(take),['♥8','♠6','♠7','♣6','♣7','♣8'].map(take)];d.drawPile=[d.trump,...pool.values()];d.attacker=0;d.defender=1;d.attackCursor=0;d.boutOrigin=0;d.composing=false;d.taking=false;d.passes=0;d.attackLimit=6;state.turn=1;};
 const defence=await session(t,'durak',{prepare:state=>setup(state)});const defend=defence.frame().projection.actions.find(a=>a.type==='defend'&&a.card==='♥8'&&a.target===1);assert(defend);const source=defence.frame().scene.interactions.find(i=>canonical(i.command)===canonical(defend)).source;
 await(await target(defence.page,source)).click();assert.equal(defence.committed.length,0);assert.equal(await defence.page.locator('.sdk-trick-defense-slot:not([disabled])').count(),2);await(await target(defence.page,{zone:'field',index:1})).click();await defence.page.waitForFunction(()=>caseRenderer.frame.projection.revision===1);assert.equal(defence.state.data.table[0].defense,null);assert.equal(defence.state.data.table[1].defense.id,'♥8');await permissions(defence);await native(defence,defence.frame().projection.actions.find(a=>a.type==='take'));await defence.viewer(defence.state.turn);await native(defence,defence.frame().projection.actions.find(a=>a.type==='done'));assert.equal(defence.state.data.table.length,0);assert.equal(await defence.page.locator('.sdk-trick-pair [data-entity]').count(),0,'empty reserved slots discard prior public identities');await permissions(defence);await defence.close();
 const transfer=await session(t,'durak',{options:{variant:'transfer'},prepare:state=>{setup(state,{transfer:true});const d=state.data,c=d.drawPile.find(c=>c.id==='♥7'),at=d.drawPile.indexOf(c);d.drawPile[at]=d.hands[1][0];d.hands[1][0]=c;}});const translated=transfer.frame().projection.actions.find(a=>a.type==='transfer');assert(translated);await native(transfer,translated);assert.equal(transfer.state.data.table.length,2);assert.equal(transfer.state.data.defender,0);await permissions(transfer);await transfer.close();
 const empty=await session(t,'durak',{prepare:state=>{
  const data=state.data;data.discard.push(...data.drawPile);data.drawPile=[];
 }});
 const emptySlot=empty.page.locator('.sdk-trick-deck > button.shared-card-slot');
 assert.equal(await emptySlot.count(),1);
 assert(await emptySlot.isVisible());
 assert(await emptySlot.isDisabled());
 assert.equal(await emptySlot.evaluate(element=>getComputedStyle(element).opacity),'0.55');
 assert.equal(await empty.page.locator('[data-motion-stock] .shared-card-back').count(),0,'an exhausted stock supplies no fictitious motion back');
 await empty.close();
 const exchange=await session(t,'durak',{options:{deck:36},prepare:state=>{setup(state,{exchange:true});state.data.attacker=1;state.data.defender=0;state.data.attackCursor=1;state.data.boutOrigin=1;}});const swap=exchange.frame().projection.actions.find(a=>a.type==='exchange');assert(swap);assert(!exchange.frame().scene.interactions.find(i=>canonical(i.command)===canonical(swap)).source,'trump exchange stays a named action, not a hand-card play');await native(exchange,swap);assert.equal(exchange.state.data.trump.id,'♠6');await permissions(exchange);await exchange.close();
 const joker=await session(t,'durak',{options:{deck:54},prepare:state=>{const d=state.data,zone=[...d.hands,d.drawPile].find(cards=>cards.some(c=>c.id==='joker-red')),at=zone.findIndex(c=>c.id==='joker-red');[zone[at],d.hands[0][0]]=[d.hands[0][0],zone[at]];d.attacker=0;d.defender=1;d.attackCursor=0;d.boutOrigin=0;d.composing=false;state.turn=0;}});assert.match(await joker.page.locator('[data-entity="card-joker-red"]').innerText(),/durak\.rank\.15/,'the bare oracle forwards the authored rank through its key-only formatter');await native(joker,joker.frame().projection.actions.find(c=>c.type==='attack'&&c.card==='joker-red'));await permissions(joker);await joker.close();

});

test('101 native preview quick play and wild drag retain explicit exact colour choices',async t=>{
 const s=await session(t,'one-oh-one',{count:4,seed:12,options:{firstPlayerMode:'assigned',firstPlayer:0}}),plays=s.frame().projection.actions.filter(a=>a.type==='play'),normal=plays.find(a=>plays.filter(b=>b.card===a.card).length===1),wild=plays.find(a=>plays.filter(b=>b.card===a.card).length>1);assert(normal&&wild,'fixed real deal contains normal and wild choices');
 const source=s.frame().scene.interactions.find(i=>canonical(i.command)===canonical(normal)).source;await (await target(s.page,source)).click();assert.equal(s.committed.length,0,'normal source tap previews before commit');const next=s.frame().scene.nextPlayerByCard[normal.card];assert.deepEqual(await s.page.locator('.sdk-player.is-next').evaluateAll(nodes=>nodes.map(n=>Number(n.dataset.owner))),next===null?[]:[next]);await s.page.locator('.sdk-cancel-selection').click();assert.equal(await s.page.locator('.sdk-player.is-next').count(),0);
 const wildInteraction=s.frame().scene.interactions.find(i=>canonical(i.command)===canonical(wild));const from=await target(s.page,wildInteraction.source),to=await target(s.page,wildInteraction.target);await from.scrollIntoViewIfNeeded();const a=await from.boundingBox(),b=await to.boundingBox();await s.page.mouse.move(a.x+a.width/2,a.y+a.height/2);await s.page.mouse.down();await s.page.mouse.move(b.x+b.width/2,b.y+b.height/2,{steps:12});await s.page.mouse.up();assert.equal(s.committed.length,0,'wild drag cannot guess a colour');await s.page.locator('.sdk-choice-panel').waitFor();const choices=plays.filter(c=>c.card===wild.card);assert.equal(await s.page.locator('.sdk-choice-panel button').count(),choices.length);const chosen=choices[2],index=await s.page.evaluate(command=>[...document.querySelectorAll('.sdk-choice-panel button')].findIndex(e=>JSON.stringify(e._command)===JSON.stringify(command)),chosen);assert(index>=0);await s.page.locator('.sdk-choice-panel button').nth(index).click();await s.page.waitForFunction(()=>caseRenderer.frame.projection.revision===1);assert.deepEqual(s.committed,[chosen]);await s.close();
 const quick=await session(t,'one-oh-one',{count:4,seed:12,options:{firstPlayerMode:'assigned',firstPlayer:0}});await quick.update({ui:{quickPlay:true}});const p=quick.frame().projection.actions.filter(a=>a.type==='play'),one=p.find(a=>p.filter(b=>b.card===a.card).length===1);assert(one);await native(quick,one);await quick.close();
});

