test('naval battle reads opposite-attacker hit and miss objects keeps one active board and follows turns',async t=>{
 const s=await session(t,'fleet-grid',{prepare:state=>{state.turn=0;Object.assign(state.data,{phase:'battle',ready:[true,true],ships:[[[0,1,2,3,4],[20,21,22,23],[40,41,42],[60,61,62],[80,81]],[[5,6,7,8,9],[25,26,27,28],[45,46,47],[65,66,67],[85,86]]],shots:[[{cell:85,hit:true},{cell:50,hit:false}],[]],marks:[[],[]],sunk:[[],[]]});}});
 assert.equal(await s.page.locator('.sdk-naval-panel.is-active').getAttribute('data-fleet-player'),'1');assert.equal(await s.page.locator('.sdk-naval-panel[data-fleet-player="1"] .sdk-naval-cell.hit').count(),1);assert.equal(await s.page.locator('.sdk-naval-panel[data-fleet-player="1"] .sdk-naval-cell.miss').count(),1);assert.equal(await s.page.locator('.sdk-naval-panel[data-fleet-player="1"] .sdk-naval-cell.ship').count(),0,'hit knowledge does not reveal hidden ship geometry');
 await s.page.getByRole('button',{name:'Мой флот',exact:true}).click();assert.equal(await s.page.locator('.sdk-naval-panel.is-active').getAttribute('data-fleet-player'),'0');await s.page.getByRole('button',{name:'Соперник',exact:true}).click();await native(s,{type:'fire',cell:86});assert.equal(s.state.data.sunk[0].length,1);assert(s.state.data.marks[0].length>0);assert.equal(await s.page.locator('.sdk-naval-panel[data-fleet-player="1"] .sdk-naval-cell.hit').count(),2);assert.equal(await s.page.locator('.sdk-naval-panel[data-fleet-player="1"] .sdk-naval-cell.miss').count(),s.state.data.marks[0].length+1);assert.equal(await s.page.locator('.sdk-naval-panel.is-active').getAttribute('data-fleet-player'),'1','manual selection is retained across turns');
 await s.page.getByRole('button',{name:'Автопереключение полей по ходу',exact:true}).click();assert.equal(await s.page.locator('.sdk-naval-panel.is-active').getAttribute('data-fleet-player'),'0','follow mode returns to the board attacked by the opponent');
 const revision=s.frame().projection.revision;
 const events=[{revision,player:0,presentation:{type:'fire',cell:86}}];
 await s.update({history:{reviewing:true},events});
 assert.equal(await s.page.locator('.sdk-naval-panel.is-active').getAttribute('data-fleet-player'),'0','a frozen live frame still follows the current turn');
 await s.update({history:{reviewing:true,index:revision},events});
 assert.equal(await s.page.locator('.sdk-naval-panel.is-active .sdk-naval-cell.hit').count(),2,'a direct history seek follows the public shot without a transition');
 assert.equal(await s.page.getByRole('button',{name:'Соперник',exact:true}).getAttribute('aria-pressed'),'true');
 await permissions(s);await s.viewer(1);assert.equal(await s.page.locator('.sdk-naval-panel.is-active').getAttribute('data-fleet-player'),'0');await native(s,{type:'fire',cell:99});assert.equal(s.state.data.shots[1].at(-1).hit,false);await permissions(s);await s.close();
});


