 await s.viewer(2);await s.page.locator('.mage-loot-hand [data-sdk-player-choice-trigger]').click();assert.equal(await dialog.locator('[data-card-index]').count(),6);await s.update({history:{reviewing:true}});assert.equal(await dialog.count(),0);assert.equal(await s.page.locator('[data-sdk-player-choice-trigger]').count(),0);await s.viewer(-1);assert.equal(s.frame().scene.playerChoices.choices.length,0);assert.equal(await s.page.locator('[data-sdk-player-choice-trigger]').count(),0);await s.close();
